/**
 * Image variants generated by the manager upload flow.
 *
 * The keys deliberately describe where an image is displayed rather than a
 * file format. This lets the public site select the right source with a
 * normal `srcset` while keeping the stored document easy to understand.
 */
export const responsiveImageWidths = {
  card: 960,
  gallery: 1440,
  hero: 1920,
} as const

export type ResponsiveImageVariant = keyof typeof responsiveImageWidths

/** A generated file and its real intrinsic dimensions. */
export interface ResponsiveImageVariantAsset {
  url: string
  /**
   * The generated image's actual intrinsic width. It may be below the target
   * size when the manager starts with a smaller source image.
   */
  width: number
  height?: number
}

export type ResponsiveImageVariantSource = string | ResponsiveImageVariantAsset

export interface ResponsiveImageVariants {
  card?: ResponsiveImageVariantSource | null
  gallery?: ResponsiveImageVariantSource | null
  hero?: ResponsiveImageVariantSource | null
}

/**
 * Compatible with the existing `{ url, alt }` image shape. `variants` is
 * optional so older packages, destinations and guides keep rendering without
 * any migration.
 */
export interface ResponsiveImageAsset {
  url?: string | null
  alt?: string | null
  variants?: ResponsiveImageVariants | null
  width?: number | null
  height?: number | null
}

/**
 * A bare variant map is also accepted for the small number of cases where an
 * image does not need its own alt text or legacy/original URL.
 */
export type ResponsiveImageSource = string | ResponsiveImageAsset | ResponsiveImageVariants | null | undefined

export interface ResolvedResponsiveImage {
  url: string
  alt: string
  variants: Record<ResponsiveImageVariant, ResolvedResponsiveImageVariant>
  width?: number
  height?: number
}

interface ResolvedResponsiveImageVariant {
  url: string
  width: number
  height?: number
}

function isVariantMap(value: Exclude<ResponsiveImageSource, string | null | undefined>): value is ResponsiveImageVariants {
  return 'card' in value || 'gallery' in value || 'hero' in value
}

function hasOwnUrl(value: Exclude<ResponsiveImageSource, string | null | undefined>): value is ResponsiveImageAsset {
  return 'url' in value || 'alt' in value || 'variants' in value || 'width' in value || 'height' in value
}

/**
 * Keeps legacy static filenames working (`munnar.jpg` becomes
 * `/images/munnar.jpg`) while preserving public Supabase URLs, root-relative
 * paths, blob previews and image data URLs.
 */
export function resolveTripportImageUrl(value?: string | null): string {
  const url = value?.trim() ?? ''
  if (!url) return ''

  if (url.startsWith('/') || url.startsWith('./') || url.startsWith('../') || url.startsWith('//')) return url
  if (/^https?:\/\//i.test(url) || /^blob:/i.test(url) || /^data:image\//i.test(url)) return url

  // Do not pass unsupported protocols such as `javascript:` through to the DOM.
  if (/^[a-z][a-z\d+.-]*:/i.test(url)) return ''

  return `/images/${url}`
}

function resolveResponsiveImageVariant(
  value: ResponsiveImageVariantSource | null | undefined,
  fallbackWidth: number,
): ResolvedResponsiveImageVariant {
  if (typeof value === 'string') return { url: resolveTripportImageUrl(value), width: fallbackWidth }
  if (!value) return { url: '', width: fallbackWidth }

  return {
    url: resolveTripportImageUrl(value.url),
    width: typeof value.width === 'number' && value.width > 0 ? value.width : fallbackWidth,
    ...(typeof value.height === 'number' && value.height > 0 ? { height: value.height } : {}),
  }
}

function emptyResolvedVariants(): Record<ResponsiveImageVariant, ResolvedResponsiveImageVariant> {
  return {
    card: { url: '', width: responsiveImageWidths.card },
    gallery: { url: '', width: responsiveImageWidths.gallery },
    hero: { url: '', width: responsiveImageWidths.hero },
  }
}

/** Turns legacy strings, asset objects and bare variant maps into one shape. */
export function resolveResponsiveImage(source?: ResponsiveImageSource): ResolvedResponsiveImage {
  if (typeof source === 'string') {
    return { url: resolveTripportImageUrl(source), alt: '', variants: emptyResolvedVariants() }
  }

  if (!source) return { url: '', alt: '', variants: emptyResolvedVariants() }

  if (isVariantMap(source) && !hasOwnUrl(source)) {
    return {
      url: '',
      alt: '',
      variants: {
        card: resolveResponsiveImageVariant(source.card, responsiveImageWidths.card),
        gallery: resolveResponsiveImageVariant(source.gallery, responsiveImageWidths.gallery),
        hero: resolveResponsiveImageVariant(source.hero, responsiveImageWidths.hero),
      },
    }
  }

  const asset = source as ResponsiveImageAsset
  return {
    url: resolveTripportImageUrl(asset.url),
    alt: asset.alt?.trim() ?? '',
    variants: {
      card: resolveResponsiveImageVariant(asset.variants?.card, responsiveImageWidths.card),
      gallery: resolveResponsiveImageVariant(asset.variants?.gallery, responsiveImageWidths.gallery),
      hero: resolveResponsiveImageVariant(asset.variants?.hero, responsiveImageWidths.hero),
    },
    ...(typeof asset.width === 'number' && asset.width > 0 ? { width: asset.width } : {}),
    ...(typeof asset.height === 'number' && asset.height > 0 ? { height: asset.height } : {}),
  }
}

/**
 * Uses the largest available optimized variant as the non-srcset fallback,
 * then falls back to the legacy/original URL.
 */
export function responsiveImageSrc(source?: ResponsiveImageSource): string {
  const image = resolveResponsiveImage(source)
  return image.variants.hero.url || image.variants.gallery.url || image.variants.card.url || image.url
}

/**
 * Returns only truthful descriptors: a source is never labelled as a width it
 * was not generated for. When all three variants exist this is a 960w,
 * 1440w, 1920w responsive source set.
 */
export function responsiveImageSrcset(source?: ResponsiveImageSource): string {
  const image = resolveResponsiveImage(source)
  const entriesByWidth = new Map<number, string>()

  for (const variant of Object.keys(responsiveImageWidths) as ResponsiveImageVariant[]) {
    const item = image.variants[variant]
    if (!item.url) continue
    // Later, larger-quality variants replace a duplicate width from a small
    // source image. A width descriptor always remains truthful.
    entriesByWidth.set(item.width, item.url)
  }

  return [...entriesByWidth.entries()]
    .sort(([left], [right]) => left - right)
    .map(([width, url]) => `${url} ${width}w`)
    .join(', ')
}

export function responsiveImageAlt(source?: ResponsiveImageSource, fallback = ''): string {
  return resolveResponsiveImage(source).alt || fallback
}
